export default async function (ctx) {
  const out = [];
  for (const u of ['http://api.example.com/', 'http://192.168.1.20:8123/api', 'http://homeassistant.local/', 'ftp://api.example.com/', 'not a url']) {
    try { await ctx.fetch(u); out.push('sent'); } catch (e) { out.push(e.code); }
  }
  return out.join(' ');
}
